import React, { Component } from 'react'
import Form from 'react-bootstrap/Form'
import Button from 'react-bootstrap/Button'
import Spinner from 'react-bootstrap/Spinner'

class SearchForm extends Component {
    
    constructor(props) {
        super(props);    
        this.handleChange = this.handleChange.bind(this);
        this.handleSubmit = this.handleSubmit.bind(this);
    }
  
    /*initialState = {
        searchUrl: '',
        enableSearchSubmitButton: false
    }

    state = this.initialState*/
  
    handleChange = event => {
        //console.log(event);
        /*const { name, value } = event.target
  
        this.setState({
          [name]: value,
            searchUrl: value
        })*/
        
        this.props.handleSearchChange(event)
        
    }
    
    handleSubmit = formData => {

        console.log(formData);
        //this.props.handleSearchSubmit(formData)
        //this.setState(this.initialState)
    }
    
    render() {
        const searchUrl = this.props.searchUrl;
        const searchUrl2 = this.props.searchUrl + '2';
 
        const showSearchSubmitButton = this.props.showSearchSubmitButton ? {display: 'block'} : {display: 'none'};
        const showSearchSubmitLoadingButton = this.props.showSearchSubmitLoadingButton ? {display: 'block'} : {display: 'none'};
        
        const enableSearchSubmitButton = searchUrl.length > 0;
        
        return (
          <Form onSubmit={this.handleSubmit}>
            <Form.Group>
                <Form.Label>Soundcloud Song URL</Form.Label>
                <Form.Control
                    type="text"
                    name="searchUrl"
                    value={searchUrl}
                    onChange={this.handleChange} />
            </Form.Group>
    
      <Form.Group>
                <Form.Label>Soundcloud Song URL</Form.Label>
                <Form.Control
                    type="text"
                    name="searchUrl2"
                    value={searchUrl2}
                    onChange={this.handleChange} />
            </Form.Group>
            
            <Button
                type="submit"
                value="Submit"
                disabled={!enableSearchSubmitButton}
                onClick={e => {e.preventDefault(); this.handleSubmit(this)}}
                style={showSearchSubmitButton}>
                Submit
            </Button>
            
              <Button variant="primary" disabled style={showSearchSubmitLoadingButton}>
                <Spinner
                  as="span"
                  animation="grow"
                  size="sm"
                  role="status"
                  aria-hidden="true"
                />
                Loading...
              </Button>
          </Form>
          
        );
    }

}

export default SearchForm;
